export const DATA_RULES = [
  [/^Ganá (\d+) minijuegos( seguidos)?( online)?\.?$/, (m) => `Win ${m[1]} minigames${m[2] ? ' in a row' : ''}${m[3] ? ' online' : ''}${m[0].endsWith('.') ? '.' : ''}`],
  [/^Jugá (\d+) minijuegos( con CAOS| online| en un mismo día)?\.?$/, (m) => `Play ${m[1]} minigames${({ ' con CAOS': ' with CHAOS', ' online': ' online', ' en un mismo día': ' in a single day' })[m[2]] || ''}${m[0].endsWith('.') ? '.' : ''}`],
  [/^Jugá (\d+) veces (.+)$/, (m) => `Play ${m[2]} ${m[1]} times`], [/^Ganale (\d+) veces a un bot$/, (m) => `Beat a bot ${m[1]} times`], [/^Terminá (\d+) competiciones$/, (m) => `Finish ${m[1]} competitions`],
  [/^Llegá a (\d+) de ELO\.$/, (m) => `Reach ${m[1]} ELO.`], [/^Llegá al nivel (\d+)\.$/, (m) => `Reach level ${m[1]}.`], [/^Llegá a la etapa (\d+) en SURVIVAL\.$/, (m) => `Reach stage ${m[1]} in SURVIVAL.`],
  [/^Reaccioná en menos de (\d+) ms en Reaction Rush\.$/, (m) => `React in under ${m[1]} ms in Reaction Rush.`],
  [/^(\d+)\/(\d+)\/(\d+) · versión (.+)$/, (m) => `${m[2]}/${m[1]}/${m[3]} · version ${m[4]}`],
];
